CREATE OR ALTER TRIGGER [reporting].[Global_Audit_AfterDelete]
	ON [reporting].[Global_Audit]
	AFTER DELETE
AS
BEGIN
	SET NOCOUNT ON;
		declare @auditID bigint;

		select @auditID = [ID] from deleted where [Object] = 'MetricAllocation';

		DELETE FROM [reporting].[Global_FieldAudit] where [AuditID] = @auditID

END
